  id: "JAH-CITE-000001",
  title: "Signature Cite One",
  kind: "citation manager",
  developer: "Corporation for Digital Scholarship",
  platforms: "Windows, macOS, Linux, any modern web browser",
  license: "Signature line"
};
function demo() {
